namespace Swoovr.Client;

/// <summary>
/// The member-facing privacy notice (#99, #22; policy §1–§16, procedure §10), shared by the web page and the app so both say
/// the same thing. It is the APP privacy policy (APP 1.3–1.4, including the APP 1.7–1.9 automated-decision disclosures that
/// commence on 10 December 2026) and the general collection notice (APP 5). Approved and in force (D288/D290/D310); every
/// rendering shows <see cref="StatusLabel"/>. Wording follows the decisions it describes (D138, D167, D170–D173, D186–D191,
/// D195, D199, D203–D205, D216, D217, D263, D266, D268, D269, D272, D275, D277, D333, D334); change them together. Provider countries in
/// "overseas" must keep matching the executed provider agreements.
/// </summary>
public static class PrivacyNotice
{
    // Issue 208: 0.19 (helpdesk, support retention and customer retirement, issue 207) approved 6 November 2026 (owner; D334).
    public const string StatusLabel = "Privacy notice — approved 6 November 2026.";
    public const string Version = "0.19, 6 November 2026";
    /// <summary>CONFIRMED (D202, Q80): privacy@swoovr.com; mail to privacy@swoovr.app forwards to it.</summary>
    public const string Contact = "privacy@swoovr.com";

    public sealed record Section(string Id, string Title, IReadOnlyList<string> Paragraphs);

    public static readonly IReadOnlyList<Section> Sections =
    [
        new("who", "Who we are", [
            "Swoovr is run by RePass Cloud Pty Ltd (ABN 74 642 243 801, ACN 642 243 801) of Findon, South Australia 5023 (\"Swoovr\", \"we\", \"us\"). This notice applies to the Swoovr website, the Swoovr iOS and Android apps, and our support and safety services. It explains what personal information we collect, how and why we collect it, who can see it, where it goes, how long we keep it, and the choices and rights you have.",
            "We handle personal information in line with the Australian Privacy Principles in the Privacy Act 1988. Swoovr is for adults only. We don't knowingly collect information from anyone under 18; if we learn an account belongs to someone under 18, we lock it and review it.",
        ]),
        new("collect", "What we collect", [
            "Your account: your email address, mobile number (verified with a code) and sign-in details, held by our sign-in service. If you sign in with Apple or Google, we receive the account identifier and email address that provider shares with us; we never receive your Apple or Google password.",
            "Your profile: display name, area, home city, date of birth (never shown to others), photos, gender, detailed identity and pronouns if you add them, sexual orientation if you add it, your connection modes, intentions, interests, filters, who you'd like to meet and abouts.",
            "What you do on Swoovr: connection requests, connections, blocks, messages, reports, appeals, trips, meeting plans, meeting-safety sessions and trusted contacts, private feedback, notices, and the policy versions you explicitly accept.",
            "Location: your home city and trip destinations, which you choose. When you confirm arrival or we check your home area, we read your device location once and keep only the outcome, never the coordinates.",
            "Technical information: the cookies and device storage that keep you signed in, protect the service and remember your preferences, including your appearance choices and manually selected Safety & Support country. We also collect notification tokens for your device if you enable notifications and the network (IP) address of requests, which we use to limit abuse and protect sign-in and verification.",
            "Information from others: verification results from Didit if you choose ID verification, and information other members or authorities give us, such as a report about you or a request from police. We may also receive information about you from someone who names you as a trusted contact.",
            "Customer support: when you contact us, we collect your support requests, correspondence, email address, relevant account details, attachments and information needed to investigate and resolve your enquiry. Support records may include messages sent by email, staff responses, internal case notes and information relating to complaints, disputes or appeals. We also retain relevant ticket history and processing records.",
        ]),
        new("why", "Why we collect and use it", [
            "We use your information to: create and secure your account; confirm you're an adult and, if you choose, verify your identity; show your profile only in the modes and to the people your settings allow; suggest people and let you connect, message and plan to meet; send the codes, notices and notifications you need; provide meeting safety if you use it; answer support requests and appeals; and keep a record of policy versions you accept.",
            "We also use it to keep Swoovr safe: screening photos and some text, investigating reports, enforcing our terms and community guidelines, keeping banned members off Swoovr, preserving evidence, responding to lawful requests from authorities, meeting our legal obligations, and preparing the aggregate reports the online dating industry code asks for.",
            "We use only what we need for each purpose. We don't sell your personal information, we don't share it with advertisers, and we don't use your messages, photos, identity record or sensitive information to train AI models or to profile you for unrelated purposes.",
            "Your mobile number, email address and date of birth are required: without them we can't create an account, confirm you're an adult or keep accounts accountable. Everything else on your profile is optional, but leaving it out may mean fewer people can find you or some features won't work.",
            "You can use a first name or nickname as your display name. Because Swoovr depends on accountable adult accounts, it isn't practicable to use Swoovr anonymously.",
        ]),
        new("sensitive", "Sensitive information and your consent", [
            "Some information is sensitive under privacy law, including your sexual orientation, intentions that reveal your sexual preferences, and the biometric checks Didit runs during ID verification. We collect sensitive information about you only with your consent, which you give by choosing to add it or to start verification, or where the law allows it without consent, for example to deal with a serious threat to someone's safety or suspected unlawful activity.",
            "Your sexual orientation is hidden from other members unless you choose to show it, and it never decides who sees you. Dating intentions appear only in the modes you choose. You can change or remove optional sensitive details at any time; removing them doesn't affect information already preserved as evidence.",
            "Reports and safety cases can contain sensitive information, including allegations of criminal conduct. A report is an allegation, not a finding, and only authorised staff handling the case can see it.",
        ]),
        new("identity", "ID verification and your identity record", [
            "ID verification is optional and done by our verification provider, Didit. Didit keeps the raw evidence (document images, selfie, liveness checks) for about 30 days; we ask Didit to delete your sessions when your account is finally deleted.",
            "If you complete ID verification, we keep a minimum identity record: your legal first and last name as on the document, the document's date of birth, the document type, the issuing country and the expiry date. We encrypt it and keep it separate from your profile.",
            "We never keep your document number, address, document images, selfie, liveness or biometric data.",
            "Only our security and legal officer can open an identity record, for a recorded reason, with time-limited access that is logged. Other staff see only that an identity is on file, when, and the issuing country.",
